import React from 'react';
import Navbar from "../components/Navbar";
import EventsSlider from "../components/EventsSlider";
import MiniSlider from '../components/MiniSlider';
import { JobCard } from '../components/JobCard';
function Home() {
  return (
    <>
      <Navbar />
      <EventsSlider />
      <MiniSlider />	
      <JobCard/>
    </>
  );
}

export default Home;
